/* ---------- Utilidades ---------- */
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const trap=(x,a,b,c,d)=>x<=a||x>=d?0:x<b?(x-a)/(b-a):x<=c?1:(d-x)/(d-c);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const RAMP=["--s0","--s1","--s2","--s3","--s4"];
const band=s=>s<25?0:s<45?1:s<65?2:s<80?3:4;
const LABEL=["Malo","Flojo","Bueno","Muy bueno","Excelente"];
const col=s=>`var(${RAMP[band(s)]})`;
const light=s=>band(s)<=1;
const fmtDay=(iso,i)=>{const d=new Date(iso+"T12:00:00");const ca=I18N.lang==="ca";return i===0?(ca?"Avui":"Hoy"):i===1?(innerWidth<520?(ca?"Demà":"Mañ."):(ca?"Demà":"Mañana")):d.toLocaleDateString(LOCALE,{weekday:"short"}).replace(".","")};
const fmtDate=iso=>new Date(iso+"T12:00:00").toLocaleDateString(LOCALE,{day:"numeric",month:"short"}).replace(".","");
const todayISO=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10)};

/* ---------- Modelo ---------- */
function computeSite(site, w, start){
  const fc = w.fc.slice(start);           // días a partir de hoy
  const lagObs = 2 + start;                 // días entre la última observación y hoy
  const out=[];
  const tObs = w.t==null ? null : w.t - 0.0065*(site.alt-site.sta);
  for(let i=0;i<Math.min(site.maxDays||9,fc.length);i++){
    let before=0, trig=0;
    for(let k=0;k<i;k++){ before+=fc[k].r; trig += (i-k>=4?1:0.4)*fc[k].r; }
    // lluvia anterior a hoy que no está en la previsión (días entre obs y hoy): aproximada con w.fc pasados
    for(let k=0;k<start;k++){ before+=w.fc[k].r; trig+=w.fc[k].r; }
    const age=lagObs+i;
    const W = w.r21*clamp(1-0.035*age) + before*0.85;
    const soil = clamp((W-20)/110);
    const lagF = age+6<=16?1:0.75;
    const trigger = clamp((w.r7*lagF + trig)/70);
    const moist = 0.55*soil + 0.45*trigger;
    const temps=[]; if(tObs!=null) temps.push(tObs);
    for(let k=0;k<=i;k++) temps.push((fc[k].lo+fc[k].hi)/2);
    const tref = temps.reduce((a,b)=>a+b,0)/temps.length;
    const tScore = trap(tref,3,8,16,22);
    /* Altitud y época: en otoño las setas empiezan arriba y van bajando. Cota central ≈1500 m a mediados de septiembre, ≈600 m a primeros de noviembre, nivel del mar en diciembre. */
    const dd=new Date(fc[i].d+"T12:00:00"); const doy=Math.round((dd-new Date(dd.getFullYear(),0,1))/864e5)+1;
    const center = seasonCenter(doy);
    const altF = site.alt < center ? clamp(1 - Math.max(0, center - site.alt - 300)/1100, 0.2, 1) : clamp(1 - Math.max(0, site.alt - center - 700)/1000, 0.3, 1);
    let minLo=99; for(let k=Math.max(0,i-2);k<=i;k++) minLo=Math.min(minLo,fc[k].lo);
    const frost = minLo<-2?0.55:minLo<0?0.8:1;
    let hs=0,ws=0,n=0; for(let k=Math.max(0,i-2);k<=i;k++){ if(fc[k].hum!=null){hs+=fc[k].hum;ws+=fc[k].wind||0;n++;} }
    const humA=n?hs/n:70, windA=n?ws/n:5;
    const dry = clamp(1 - Math.max(0,62-humA)/90 - Math.max(0,windA-14)/70, 0.7, 1);
    const tz = TERR[site.id]; const optAlt = tz ? Math.round(clamp(site.alt + (((fc[i].lo+fc[i].hi)/2) - 12)/0.0065, tz[2], tz[3])/50)*50 : site.alt;
    const score0 = Math.round(100*Math.min(1,moist*1.08)*tScore*frost*dry*altF);
    const mo=dd.getMonth()+1, prevM=mo===1?12:mo-1, nextM=mo===12?1:mo+1;
    const soilK=(typeof TERR!=="undefined"&&TERR[site.id])?TERR[site.id][0]:(site.soil||"mixto");
    const cand=[...new Set([...site.sp,...(EXTRA[soilK]||[])])];
    const inS=id=>{const m=MONTHS[id]; if(!m) return 1; return m.includes(mo)?1:(m.includes(prevM)||m.includes(nextM))?0.35:0;};
    const sp0 = cand.map(id=>{const t=SP[id].t;const fit=trap(tref,t[0]-4,t[0],t[1],t[1]+4);const se=inS(id);return {id,se,p:Math.round(score0*se*(site.sp.includes(id)?1:0.8)*(0.35+0.65*fit))}}).filter(x=>x.se>0&&(site.sp.includes(x.id)||x.se===1)).sort((a,b)=>b.p-a.p).slice(0,6);
    /* Época del año: en otoño salen muchas especies; en primavera pocas (moixernó, múrgola) y en invierno casi nada */
    const bestSe=sp0.length?Math.max(...sp0.map(x=>x.se)):0;
    const seasonF=MPROD[mo]*(bestSe>=1?1:bestSe>0?0.6:0.2);
    const score=Math.round(score0*seasonF);
    const sp=sp0.map(x=>({...x,p:Math.round(x.p*seasonF)}));
    out.push({d:fc[i].d,score,altF,center:Math.round(center/50)*50,W:Math.round(W),soil,trigger,recent:Math.round(w.r7*lagF+trig),tref,tScore,minLo,frost,rain:fc[i].r,lo:fc[i].lo,hi:fc[i].hi,hum:fc[i].hum,wind:fc[i].wind,gust:fc[i].gust,dry,optAlt,sp});
  }
  return out;
}
/* Tendencia de la segunda semana (días 10-14): sin previsión fiable, se calculan dos escenarios
   con la temperatura de los últimos días previstos: sin más lluvia y con lluvia normal de otoño (2,5 mm/día). */
function computeTrend(site, w, start){
  const real=w.fc.slice(start); if(real.length<5) return null;
  const last=real.slice(-3), lo=last.reduce((a,f)=>a+f.lo,0)/3, hi=last.reduce((a,f)=>a+f.hi,0)/3;
  const base=new Date(real[real.length-1].d+"T12:00:00");
  const ext=r=>{const fc=[...w.fc]; for(let k=1;fc.length-start<14;k++){const d=new Date(base.getTime()+k*864e5); fc.push({d:d.toISOString().slice(0,10),lo:+lo.toFixed(1),hi:+hi.toFixed(1),r,hum:70,wind:5,gust:10});} return {...w,fc};};
  const S={...site,maxDays:14};
  const dry=computeSite(S,ext(0),start).slice(9,14), wet=computeSite(S,ext(2.5),start).slice(9,14);
  if(!dry.length) return null;
  const av=a=>Math.round(a.reduce((x,r)=>x+r.score,0)/a.length);
  const lowV=av(dry), highV=av(wet), now=av(computeSite(site,w,start).slice(0,7));
  const mid=(lowV+highV)/2;
  return {from:dry[0].d, to:dry[dry.length-1].d, low:Math.min(lowV,highV), high:Math.max(lowV,highV), now, dir: mid>now+8?"up":mid<now-8?"down":"flat"};
}

if(typeof module!=='undefined') module.exports={SITES,computeSite,computeTrend,zoneWeather,SP};
